#include "my_hw/my_hw_system.hpp"

#include <limits>
#include <string>
#include <vector>

#include "hardware_interface/types/hardware_interface_type_values.hpp"
#include "rclcpp/logging.hpp"

namespace my_hw
{

hardware_interface::CallbackReturn MyHwSystemHardware::on_init(
  const hardware_interface::HardwareInfo & info)
{
  if (
    hardware_interface::SystemInterface::on_init(info) !=
    hardware_interface::CallbackReturn::SUCCESS)
  {
    return hardware_interface::CallbackReturn::ERROR;
  }

  for (const hardware_interface::ComponentInfo & joint : info_.joints)
  {
    // Each joint must expose exactly one position command interface.
    if (joint.command_interfaces.size() != 1)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MyHwSystemHardware"),
        "Joint '%s' has %zu command interfaces, expected 1 (position).", joint.name.c_str(),
        joint.command_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }
    if (joint.command_interfaces[0].name != hardware_interface::HW_IF_POSITION)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MyHwSystemHardware"),
        "Joint '%s' command interface is '%s', expected '%s'.", joint.name.c_str(),
        joint.command_interfaces[0].name.c_str(), hardware_interface::HW_IF_POSITION);
      return hardware_interface::CallbackReturn::ERROR;
    }

    // Each joint must expose position and velocity state interfaces.
    if (joint.state_interfaces.size() != 2)
    {
      RCLCPP_FATAL(
        rclcpp::get_logger("MyHwSystemHardware"),
        "Joint '%s' has %zu state interfaces, expected 2 (position, velocity).",
        joint.name.c_str(), joint.state_interfaces.size());
      return hardware_interface::CallbackReturn::ERROR;
    }
  }

  hw_position_commands_.resize(info_.joints.size(), 0.0);
  hw_position_states_.resize(info_.joints.size(), 0.0);
  hw_velocity_states_.resize(info_.joints.size(), 0.0);

  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHwSystemHardware::on_activate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  // Bring up the simulated hardware at rest, starting from whatever the
  // state interfaces currently hold (e.g. 0 on first activation).
  for (std::size_t i = 0; i < info_.joints.size(); ++i)
  {
    const std::string & joint_name = info_.joints[i].name;
    hw_position_states_[i] = get_state<double>(joint_name + "/" + hardware_interface::HW_IF_POSITION);
    hw_velocity_states_[i] = 0.0;
    hw_position_commands_[i] = hw_position_states_[i];

    set_state(joint_name + "/" + hardware_interface::HW_IF_POSITION, hw_position_states_[i]);
    set_state(joint_name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocity_states_[i]);
    set_command(joint_name + "/" + hardware_interface::HW_IF_POSITION, hw_position_commands_[i]);
  }

  RCLCPP_INFO(rclcpp::get_logger("MyHwSystemHardware"), "Hardware activated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::CallbackReturn MyHwSystemHardware::on_deactivate(
  const rclcpp_lifecycle::State & /*previous_state*/)
{
  RCLCPP_INFO(rclcpp::get_logger("MyHwSystemHardware"), "Hardware deactivated.");
  return hardware_interface::CallbackReturn::SUCCESS;
}

hardware_interface::return_type MyHwSystemHardware::read(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & /*period*/)
{
  // No physical hardware to poll: the state was already updated in write()
  // to reflect the last commanded position, so just publish it back out.
  for (std::size_t i = 0; i < info_.joints.size(); ++i)
  {
    const std::string & joint_name = info_.joints[i].name;
    set_state(joint_name + "/" + hardware_interface::HW_IF_POSITION, hw_position_states_[i]);
    set_state(joint_name + "/" + hardware_interface::HW_IF_VELOCITY, hw_velocity_states_[i]);
  }
  return hardware_interface::return_type::OK;
}

hardware_interface::return_type MyHwSystemHardware::write(
  const rclcpp::Time & /*time*/, const rclcpp::Duration & period)
{
  const double dt = period.seconds();

  for (std::size_t i = 0; i < info_.joints.size(); ++i)
  {
    const std::string & joint_name = info_.joints[i].name;
    hw_position_commands_[i] = get_command<double>(joint_name + "/" + hardware_interface::HW_IF_POSITION);

    // Integrate the command directly into the state: the simulated hardware
    // "moves" instantly to the commanded position, and velocity is derived
    // from the resulting position change over this control period.
    const double previous_position = hw_position_states_[i];
    hw_position_states_[i] = hw_position_commands_[i];
    hw_velocity_states_[i] =
      dt > std::numeric_limits<double>::epsilon()
        ? (hw_position_states_[i] - previous_position) / dt
        : 0.0;
  }

  return hardware_interface::return_type::OK;
}

}  // namespace my_hw

#include "pluginlib/class_list_macros.hpp"

PLUGINLIB_EXPORT_CLASS(my_hw::MyHwSystemHardware, hardware_interface::SystemInterface)

